<template><div><el-table :data="rows" row-key="id" border><el-table-column v-if="showUser" label="User" width="170"><template slot-scope="s"><el-button type="text" @click="$router.push('/commercialization/users/'+s.row.userId)">{{ s.row.userName }}</el-button><div class="item-code">{{ s.row.userId }}</div></template></el-table-column><el-table-column v-for="column in columns" :key="column.key" :label="column.label" :min-width="column.width||140"><template slot-scope="s"><span :class="column.key==='amount'?'amount-value':''">{{ cell(s.row,column.key) }}</span></template></el-table-column><el-table-column label="Actions" width="185" fixed="right"><template slot-scope="s"><el-button type="text" @click="selected=s.row">Details</el-button><el-button v-if="kind==='orders' && s.row.status==='paid' && s.row.fulfillment!=='completed'" type="text" :disabled="busy" @click="retry(s.row)">Retry Delivery</el-button><el-button v-if="kind==='subscriptions' && s.row.status!=='expired'" type="text" :disabled="busy" @click="renew(s.row)">{{ s.row.autoRenew?'Cancel Renewal':'Resume Renewal' }}</el-button></template></el-table-column></el-table>
<el-dialog v-if="selected" :title="detailTitle" :visible="!!selected" width="820px" @close="selected=null"><dl class="read-detail"><dt>Record ID</dt><dd class="item-code">{{ selected.id }}</dd><dt v-if="selected.userName">User</dt><dd v-if="selected.userName">{{ selected.userName }} · {{ selected.userId }}</dd><template v-for="column in columns"><dt :key="column.key+'l'">{{ column.label }}</dt><dd :key="column.key+'v'">{{ cell(selected,column.key) }}</dd></template><template v-if="selected.reference"><dt>Reference</dt><dd class="item-code">{{ selected.reference }}</dd></template></dl>
<template v-if="kind==='orders'"><h3>Purchased configuration</h3><commerce-summary :config="selected.product"/><p v-if="selected.subscriptionTimeZone">Subscription time zone: {{ selected.subscriptionTimeZone }}</p><p v-if="selected.suit">Suit: {{ selected.suit.config.name }} v{{ selected.suit.version }} · {{ dateTime(selected.startsAt) }} → {{ dateTime(selected.expiresAtMembership) }}</p><p class="field-help">Retry only delivers an already paid snapshot. It creates no new payment or duplicate benefits.</p></template>
<template v-if="selected.allocations && selected.allocations.length"><h3>Credits allocations · Earliest expiry first</h3><el-table :data="selected.allocations" border><el-table-column prop="batchId" label="Batch" min-width="220"/><el-table-column prop="amount" label="Credits" width="90"/><el-table-column prop="source" label="Source" width="125"/><el-table-column label="Expires" min-width="180"><template slot-scope="s">{{ s.row.expiresAt ? dateTime(s.row.expiresAt) : "No expiry" }}</template></el-table-column></el-table></template>
<template v-if="kind==='subscriptions'"><p v-if="selected.subscriptionTimeZone">Original subscription time zone: {{ selected.subscriptionTimeZone }}</p><h3>Purchased period · v{{ selected.grant.version }}</h3><p>{{ dateTime(selected.grant.startsAt) }} → {{ dateTime(selected.grant.expiresAt) }}</p><commerce-summary :config="selected.grant.config"/><p class="field-help">Changing renewal preserves the paid period, its suit version and saved assets. Store synchronization is a demo adapter.</p></template>
<template v-if="kind==='usage'"><p v-if="selected.allowance">Included action · grant {{ selected.allowance.grantId }} · original period {{ dateTime(selected.allowance.periodStart) }} → {{ dateTime(selected.allowance.resetAt) }}</p><p>Locked price v{{ selected.priceVersion }} · {{ selected.credits }} Credits · hold expires {{ dateTime(selected.leaseExpiresAt) }}</p><p v-if="selected.message" class="asset-body">{{ selected.message }}</p><el-button v-if="selected.assetId" @click="openAsset(selected)">Read Saved Result</el-button></template>
<template v-if="kind==='redemptions'"><p>Content snapshot v{{ selected.contentVersion }} · {{ selected.credits }} Credits · {{ selected.source }}</p><p v-if="selected.contentType==='training_program'" class="field-help">This Program unlock includes the snapshotted workouts when accessed through its verified Program context. No duplicate course redemption is required.</p></template>
<el-table v-if="kind==='campaign-runs'" :data="selected.results" border><el-table-column prop="name" label="User"/><el-table-column prop="status" label="Result"/><el-table-column prop="credits" label="Extra Credits"/><el-table-column prop="reason" label="Reason"/></el-table>
<template v-if="kind==='audit'"><h3>Operation context</h3><dl class="read-detail"><template v-for="entry in auditContext"><dt :key="entry.key+'l'">{{ entry.key }}</dt><dd :key="entry.key+'v'">{{ entry.value }}</dd></template></dl><commerce-summary v-if="selected.payload.config" :config="selected.payload.config"/></template><span slot="footer"><el-button @click="selected=null">Close</el-button></span></el-dialog>
<el-dialog title="Saved Asset" :visible.sync="assetVisible" width="700px"><template v-if="savedAsset"><h3>{{ savedAsset.title }}</h3><p class="asset-body">{{ savedAsset.body }}</p><p class="field-help">Reading does not spend Credits. Current AI insights require feature access; historical results retain their original contract.</p></template></el-dialog></div></template>
<script>
import {retryFulfillment,setRenewal,getAsset,money} from '@/api/commerce'
import {dateTime} from '@/utils/format'
import CommerceSummary from '@/components/CommerceSummary'
const fields={ledger:[['creditType','Credit Type',170],['type','Event',110],['amount','Credits',95],['reason','Reason',210],['createdAt','Created',175]],orders:[['productName','Product',190],['price','Price',100],['status','Payment',95],['fulfillment','Fulfillment',120],['createdAt','Created',175]],subscriptions:[['productName','Product',190],['status','Period',100],['renewal','Renewal',100],['expires','Period Ends',180]],redemptions:[['creditType','Credit Type',170],['name','Content',210],['contentType','Type',150],['credits','Credits',90],['source','Source',110],['expiresAt','Valid Until',180],['status','Status',100]],usage:[['creditType','Credit Type',170],['unit','Unit',125],['name','Service',195],['billingSource','Charged from',130],['objectKey','Source object',150],['credits','Credits',90],['status','Status',105],['priceVersion','Price Version',110],['createdAt','Created',175]],'campaign-runs':[['campaignName','Campaign',190],['version','Version',90],['caseRef','Case',125],['delivered','Delivered',90],['skipped','Skipped',85],['reason','Reason',195],['createdAt','Created',175]],audit:[['action','Operation',185],['actor','Actor',140],['targetId','Target',240],['createdAt','Created',175]]}
const events={CONSUME:'Consumed',REFUND:'Refunded',GRANT:'Issued',RESERVE:'Reserved',RELEASE:'Released',SPEND:'Spent',EXPIRE:'Expired'}
export default{components:{CommerceSummary},props:{kind:{type:String,required:true},rows:{type:Array,default:()=>[]},showUser:{type:Boolean,default:true}},data(){return{selected:null,busy:false,assetVisible:false,savedAsset:null}},computed:{columns(){return(fields[this.kind]||[]).map(([key,label,width])=>({key,label,width}))},detailTitle(){return this.kind==='ledger'?'Credits Event':this.kind==='audit'?'Audit Event':'Record Snapshot'},auditContext(){if(!this.selected||!this.selected.payload)return[];return Object.entries(this.selected.payload).filter(([key])=>!['config','results'].includes(key)).map(([key,value])=>({key,value:typeof value==='object'?Array.isArray(value)?value.length+' entries':'Recorded snapshot':String(value)}))}},methods:{dateTime,cell(row,key){if(key==='productName')return row.product?row.product.name:row.productName;if(key==='price')return money(row.sku.priceCents,row.sku.currency);if(key==='expires')return dateTime(row.grant.expiresAt);if(['createdAt','expiresAt'].includes(key))return dateTime(row[key]);if(key==='amount')return(row.amount>0?'+':'')+row.amount;if(key==='type')return events[row.type]||row.type;return row[key]===undefined?'—':row[key]},async retry(row){try{await this.$confirm('Retry fulfillment of this paid snapshot? Existing configuration versions are preserved.','Retry Delivery',{confirmButtonText:'Retry'})}catch(_){return}this.busy=true;try{await retryFulfillment(row.id);this.$message.success('Fulfillment completed.');this.$emit('changed')}catch(_){}finally{this.busy=false}},async renew(row){let result;try{result=await this.$prompt('Enter a reason. The existing paid period stays active until its original expiry.',row.autoRenew?'Cancel Renewal':'Resume Renewal',{inputValidator:value=>!!value&&value.trim().length>=3, inputErrorMessage:'Use at least 3 characters.',confirmButtonText:'Confirm'})}catch(_){return}this.busy=true;try{await setRenewal(row.id,!row.autoRenew,result.value);this.$emit('changed')}catch(_){}finally{this.busy=false}},async openAsset(row){this.savedAsset=await getAsset(row.userId,row.assetId);this.assetVisible=true}}}
</script>
